VALUES (1213, 'tt0134119', NULL, 'The Talented Mr. Ripley', 'The Talented Mr. Ripley', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/6ojHgqtIR41O2qLKa7LFUVj0cZa.jpg', 'https://image.tmdb.org/t/p/original/nGVe984XESYhn5V5zspqQexPekA.jpg', 'Tom Ripley is a calculating young man who believes it''s better to be a fake somebody than a real nobody. Opportunity knocks in the form of a wealthy U.S. shipbuilder who hires Tom to travel to Italy to bring back his playboy son, Dickie. Ripley worms his way into the idyllic lives of Dickie and his girlfriend, plunging into a daring scheme of duplicity, lies and murder.', NULL, NULL, 7.3001, 7.196, 0, 6.85544615384615383e+01, '2026-07-15 12:01:52', '2026-10-17 12:17:44')
