VALUES (10086, 'tt0103905', NULL, 'Man Bites Dog', 'C''est arrivé près de chez vous', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/uRVI98a6MxdLkpsXM8LqIM9W7XZ.jpg', 'https://image.tmdb.org/t/p/original/7QLGk7qKm66dtjTtpVeAIRocoan.jpg', 'The activities of rampaging, indiscriminate serial killer Ben are recorded by a willingly complicit documentary team, who eventually become his accomplices and active participants. Ben provides casual commentary on the nature of his work and arbitrary musings on topics of interest to him, such as music or the conditions of low-income housing, and even goes so far as to introduce the documentary crew to his family. But their reckless indulgences soon get the better of them.', NULL, NULL, 3.5158, 7.229, 0, 1.66307142857142835e+01, '2026-08-06 03:21:20', '2026-10-17 12:17:44')
