VALUES (25969, 'tt0112368', NULL, 'Angus', 'Angus', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/x1Py4TB8Y0Wx9IZ62derpSDqwjd.jpg', 'https://image.tmdb.org/t/p/original/qGW0LutVJfqEkBGooJj3w9ngLV8.jpg', 'Angus is a large, pathetic 14-year-old whose thoughts are most often filled with the image of only one girl, Melissa Lefevre. Angus is shy and thinks that he has no chance of ever ''getting'' her. Being especially uncool, he is incredibly surprised (along with the rest of the school) that he is chosen to dance with her at the Winter Ball. The only one not surprised is the cool kid who set him up to fail, but Angus'' best friend is going to help him win the heart of Melissa by developing a new look for him', NULL, NULL, 2.4333, 6.6, 0, 1.22279999999999979e+01, '2026-08-11 02:46:38', '2026-10-17 12:17:44')
