VALUES (10536, 'tt0064505', NULL, 'The Italian Job', 'The Italian Job', 'movie', 1969, 'https://image.tmdb.org/t/p/w500/8NOw3HPHkcBndJW2K6ofbcSb7WD.jpg', 'https://image.tmdb.org/t/p/original/jkYdRAhshaRwiRAB4KdDz1Ocj4e.jpg', 'Charlie''s got a ''job'' to do. Having just left prison he finds one of his friends has attempted a high-risk job in Torino, Italy, right under the nose of the mafia. Charlie''s friend doesn''t get very far, so Charlie takes over the ''job''. Using three Mini Coopers, a couple of Jaguars, and a bus, he hopes to bring Torino to a standstill, steal a fortune in gold and escape in the chaos.', NULL, NULL, 7.7469, 6.937, 0, 6.555, '2026-08-12 02:31:31', '2026-10-17 12:17:44')
